package io.github.diodeme.ji.workspace.local;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.WorkspaceProvider;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledOnOs;
import org.junit.jupiter.api.condition.OS;

@EnabledOnOs(OS.WINDOWS)
class WindowsWorkspaceSmokeTest {
    @Test
    void rejectsJunctionThatResolvesOutsideWorkspace() {
        String configured = System.getenv("JI_WORKSPACE_SMOKE_ROOT");
        if (configured == null) return;
        try (var workspace = new LocalWorkspaceProvider("workspace-windows", Path.of(configured))) {
            JiException failure = assertThrows(JiException.class,
                    () -> workspace.resolve("escape/protected.txt", WorkspaceProvider.Access.READ));
            assertEquals(ErrorCode.WORKSPACE_PATH_OUTSIDE, failure.error().code());
        }
    }
}
